pm.test("o resumo de valores é idêntico ao do cálculo do mesmo carrinho", function (done) {
    const itens = JSON.parse(pm.collectionVariables.get("itensArray"));
    const cupom = pm.collectionVariables.get("cupomBemVindo");

    pm.sendRequest({
        url: pm.environment.get("base_url") + "/carrinho/calcular",
        method: "POST",
        header: {
            "Content-Type": "application/json"
        },
        body: {
            mode: "raw",
            raw: JSON.stringify({
                itens,
                cupom
            })
        }
    }, function (err, response) {

        if (err) {
            return done(err);
        }

        const responseCalc = response.json();

        try {
            pm.expect(responseCalc.total).to.equal(responseBody.total);
            pm.expect(responseCalc.subtotal).to.equal(responseBody.subtotal);
            pm.expect(responseCalc.desconto).to.equal(responseBody.desconto);
            pm.expect(responseCalc.frete).to.equal(responseBody.frete);

            done();

        } catch (e) {
            done(e);
        }
    });
});
